function canFinish(numCourses: number, prerequisites: number[][]): boolean {
  // Ребро b -> a: курс b нужно пройти перед курсом a
  const graph: number[][] = Array.from({ length: numCourses }, () => []);
  for (const [a, b] of prerequisites) graph[b].push(a);

  // 0 — не посещён, 1 — в текущем пути DFS, 2 — полностью обработан
  const state = new Array<number>(numCourses).fill(0);

  // Возвращает true, если из course нельзя попасть в цикл
  const dfs = (course: number): boolean => {
    if (state[course] === 1) return false; // вернулись в вершину текущего пути — цикл
    if (state[course] === 2) return true; // уже проверена ранее, циклов через неё нет

    state[course] = 1;
    for (const next of graph[course]) {
      if (!dfs(next)) return false;
    }
    state[course] = 2; // все потомки проверены — выходим из пути
    return true;
  };

  // Граф может быть несвязным — запускаем DFS из каждой вершины
  for (let c = 0; c < numCourses; c++) {
    if (!dfs(c)) return false;
  }
  return true;
}

// Время: O(V + E) — каждая вершина и каждое ребро обрабатываются один раз
// Память: O(V + E) — граф, массив состояний и стек рекурсии
